def _add_from_scrape(scraped: dict, key: str, seen_at: str) -> dict:
    out = dict(scraped)
    out["idempotency_key"] = key
    out["fetched"] = out.get("fetched") or seen_at
    out["last_seen"] = seen_at
    out["closed_at"] = ""
    out["listing_misses"] = 0
    return out


