    existing: list[dict],
    scraped: list[dict],
    still_listed: list[dict] | None = None,
) -> tuple[list[dict], int, int, int, list[dict]]:
    seen_at = now_iso()
    cache = _index_existing_by_key(existing)

    merged: list[dict] = []
    scraped_keys: set[str] = set()
    preserved = 0
    new_count = 0
    new_jobs: list[dict] = []

    for job in scraped:
        key = job_idempotency_key(job.get("url", ""))
        if not key or key in scraped_keys:
            continue
        scraped_keys.add(key)

        old = cache.get(key)
        if old is not None:
            merged.append(_update_from_scrape(old, job, key, seen_at))
            preserved += 1
        else:
            merged.append(_add_from_scrape(job, key, seen_at))
            new_count += 1
            new_jobs.append(merged[-1])

    listed_keys = scraped_keys if still_listed is None else {
        job_idempotency_key(j.get("url", "")) for j in still_listed
    } - {""}
    stale_kept = 0
    for key, old in cache.items():
        if key in scraped_keys:
            continue
        kept = dict(old)
        stamp_job_identity(kept)
        if key in listed_keys:
            kept["closed_at"] = ""
            kept["last_seen"] = seen_at
        else:
            if not (kept.get("closed_at") or "").strip():
                kept["closed_at"] = seen_at
            stale_kept += 1
        merged.append(kept)

    for job in merged:
        stamp_job_identity(job)

    return merged, preserved, new_count, stale_kept, new_jobs

